<section class="overflow-hidden rounded-2xl border border-slate-200 bg-white">
    <div class="flex flex-wrap items-center justify-between gap-3 border-b border-slate-100 p-5"><div><h2 class="font-semibold" x-text="state.status === 'waiting' ? 'Player queue' : 'Players'"></h2><p class="mt-1 text-xs text-slate-400" x-text="state.status === 'waiting' ? 'Joined players, in arrival order. Ready status updates live.' : state.status === 'in_progress' ? 'A check means the current question is answered.' : 'The party for this session.'"></p></div><span class="rounded-full bg-indigo-50 px-3 py-1.5 text-xs font-semibold text-indigo-600" x-text="state.player_count + ' / ' + state.max_players"></span></div>
    <div class="roster-grid"><template x-for="person in state.players" :key="person.public_id"><article class="flex min-w-0 items-center gap-3 p-4"><div class="relative shrink-0"><img :src="person.profile?.avatar_url" alt="" class="h-12 w-12 rounded-xl bg-slate-100" width="48" height="48" loading="lazy"><template x-for="token in (state.status === 'in_progress' && answeredCurrent(person) ? [checkKey(person)] : [])" :key="token"><span class="answer-check answer-check--small answer-check--pulse" role="img" :aria-label="person.name + ' answered this question'"><svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="m5 12 4 4 10-10" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/></svg></span></template></div><div class="min-w-0 flex-1"><p x-show="state.status === 'waiting'" class="text-[10px] font-semibold tabular-nums text-slate-400" x-text="'#' + person.queue_position"></p><h3 class="break-words text-sm font-semibold" :title="person.name" x-text="person.name"></h3><div x-show="state.status === 'waiting'" class="mt-2 flex flex-wrap items-center gap-2"><span class="queue-ready-status" :class="person.is_ready ? 'queue-ready-status--ready' : ''" x-text="person.is_ready ? '✓ Ready' : 'Not ready'"></span><button x-show="state.player?.public_id === person.public_id" type="button" class="queue-ready-button" @click="toggleReady()" :disabled="readySaving || profileSaving" :aria-pressed="person.is_ready === true" x-text="readySaving ? 'Saving…' : person.is_ready ? 'Not ready' : 'Ready'"></button></div></div></article></template><p x-show="state.player_count === 0" class="col-span-full px-6 py-10 text-center text-sm leading-6 text-slate-400">No players yet. Share the game link to gather a party.</p></div>
</section>
